import{_ as n,c as t,o as i,ah as s}from"./chunks/framework.CAZQ2vdu.js";const r="/Qonnectra-docs/pr-17/images/manual/teil-a/trace.jpg",a="/Qonnectra-docs/pr-17/images/manual/teil-a/trace_search.jpg",d="/Qonnectra-docs/pr-17/images/manual/teil-a/trace_fiber_picker.jpg",l="/Qonnectra-docs/pr-17/images/manual/teil-a/trace_result.jpg",o="/Qonnectra-docs/pr-17/images/manual/teil-a/trace_tree.jpg",u="/Qonnectra-docs/pr-17/images/manual/teil-a/trace_paths_table.jpg",h="/Qonnectra-docs/pr-17/images/manual/teil-a/trace_signal.jpg",g="/Qonnectra-docs/pr-17/images/manual/teil-a/trace_geometry.jpg",c="/Qonnectra-docs/pr-17/images/manual/teil-a/trace_map.jpg",A=JSON.parse('{"title":"15. Faserweg","description":"","frontmatter":{},"headers":[],"relativePath":"manual/teil-a-anwenderhandbuch/15-faserweg.md","filePath":"manual/teil-a-anwenderhandbuch/15-faserweg.md"}'),m={name:"manual/teil-a-anwenderhandbuch/15-faserweg.md"};function b(p,e,k,f,w,S){return i(),t("div",null,[...e[0]||(e[0]=[s('<h1 id="_15-faserweg" tabindex="-1">15. Faserweg <a class="header-anchor" href="#_15-faserweg" aria-label="Permalink to &quot;15. Faserweg&quot;">​</a></h1><p>Der <strong>Faserweg</strong> verfolgt eine Faser durch das Netz: von einem Einstiegspunkt über Kabel und Spleiße bis zu den Adressen und Wohneinheiten, die an ihr hängen. Sie erreichen ihn über die linke Navigationsleiste in der Gruppe „Kabel“ durch Klicken auf den Menüpunkt „Faserweg“.</p><p><img src="'+r+'" alt="Screenshot der Ansicht Faserweg mit den fünf Einstiegspunkten und dem Suchfeld" data-zoomable="true"></p><p>Die Ansicht liest nur: Sie ändert nichts am Datenbestand und speichert kein Ergebnis. Was sie zeigt, entsteht im Netzschema, siehe Kapitel <a href="./14-netzschema.html">Netzschema</a> – vor allem die Spleiße, denn ohne sie endet jede Verfolgung am ersten Kabel.</p><h2 id="_15-1-einstiegspunkt-wahlen-adresse-netzknoten-kabel-wohneinheit-faser" tabindex="-1">15.1 Einstiegspunkt wählen: Adresse, Netzknoten, Kabel, Wohneinheit, Faser <a class="header-anchor" href="#_15-1-einstiegspunkt-wahlen-adresse-netzknoten-kabel-wohneinheit-faser" aria-label="Permalink to &quot;15.1 Einstiegspunkt wählen: Adresse, Netzknoten, Kabel, Wohneinheit, Faser&quot;">​</a></h2><p>Oben stehen die fünf Arten von Einstiegspunkten: „Adresse“, „Netzknoten“, „Kabel“, „Wohneinheiten“ und „Faser“. Jede hat ihr eigenes Suchfeld; die Suche beginnt ab zwei Zeichen, bis dahin steht dort „Mindestens 2 Zeichen eingeben zum Suchen“.</p><p>Jeder Treffer nennt in der ersten Zeile das Objekt und darunter eine Zusatzangabe – bei Adressen die Adress-ID, bei Netzknoten den Netzknotentyp, bei Kabeln den Kabeltyp, bei Wohneinheiten die Adresse. Ein Klick startet die Verfolgung.</p><p><img src="'+a+'" alt="Screenshot der Ansicht Faserweg mit Hervorhebung des Suchfeldes und der Trefferliste zu einer Adresse" data-zoomable="true"></p><p>Was verfolgt wird, hängt vom Einstiegspunkt ab:</p><ul><li><strong>Adresse</strong> – alle Fasern, die an den Netzknoten und Wohneinheiten dieser Adresse enden.</li><li><strong>Netzknoten</strong> – alle Fasern, die durch ihn laufen.</li><li><strong>Kabel</strong> – alle Fasern des Kabels.</li><li><strong>Wohneinheit</strong> – die Faser, die auf dem Port dieser Wohneinheit liegt.</li><li><strong>Faser</strong> – genau diese eine Faser. Nur dieser Einstieg kennt die Signalanalyse (siehe Abschnitt <a href="#_15-4-signalquelle-signalreichweite-und-unterbrechungen">Signalquelle, Signalreichweite und Unterbrechungen</a>) und die Karte (siehe Abschnitt <a href="#_15-6-geometrie-modus-ausrichtung-geojson-download">Geometrie</a>).</li></ul><p>Der Reiter „Faser“ verlangt zwei Schritte: Suchen Sie zuerst das Kabel („Wählen Sie ein Kabel, um dessen Fasern anzuzeigen“). Danach steht das gewählte Kabel mit Kabeltyp und Faserzahl oben, darunter seine Bündel. Klappen Sie ein Bündel auf, stehen dessen Fasern mit „#“ und „Farbe“ darin; „Folgen“ startet die Verfolgung.</p><p><img src="'+d+'" alt="Screenshot der Ansicht Faserweg mit Hervorhebung des ausgewählten Kabels und der Fasern des ersten Bündels" data-zoomable="true"></p><p>Das Kreuz am rechten Rand der Kabelzeile führt zurück zur Kabelsuche.</p><div class="info custom-block"><p class="custom-block-title">Hinweis</p><p>Die Suche ist fehlertolerant und sucht nach Ähnlichkeit: „Toft 1“ liefert auch Toft 10 bis Toft 21. Achten Sie deshalb auf die Zusatzangabe unter dem Treffer, bevor Sie klicken.</p></div><div class="info custom-block"><p class="custom-block-title">Hinweis</p><p>Denselben Faserweg erreichen Sie aus anderen Ansichten heraus über die Schaltfläche „Folgen“ – an einem Netzknoten und einer Adresse in der Karte (siehe Abschnitt <a href="./05-karte.html#_5-7-von-der-karte-in-den-faserweg-wechseln">Von der Karte in den Faserweg wechseln</a>), an einem Kabel und einer Faser in der Kabelübersicht einer Trasse und an einer aufgelegten Faser im Netzschema (siehe Abschnitt <a href="./14-netzschema.html#_14-8-spleiße-und-ports">Spleiße und Ports</a>).</p></div><h2 id="_15-2-weg-lesen-kabelpfad-spleiße-containerpfad" tabindex="-1">15.2 Weg lesen: Kabelpfad, Spleiße, Containerpfad <a class="header-anchor" href="#_15-2-weg-lesen-kabelpfad-spleiße-containerpfad" aria-label="Permalink to &quot;15.2 Weg lesen: Kabelpfad, Spleiße, Containerpfad&quot;">​</a></h2><p>Das Ergebnis ist immer gleich aufgebaut: „Statistiken“, „Einstiegspunkt“, „Kabelinfrastruktur“ und „Faserwege“. „Zurück“ oben links führt zur Auswahl des Einstiegspunkts.</p><p><img src="'+l+'" alt="Screenshot des Ergebnisses eines Faserwegs für eine Adresse mit Statistiken, Einstiegspunkt, Kabelinfrastruktur und der Tabelle der Faserwege" data-zoomable="true"></p><p>Die <strong>Statistiken</strong> zählen, was auf dem Weg liegt: „Fasern“, „Netzknoten“, „Spleiss“, „Kabel“, „Gräben“, „Adressen“ und „Wohneinheiten“. „Verzweigungen“ zählt nicht, sondern steht auf „Ja“ oder „Nein“, je nachdem, ob sich der Weg irgendwo aufteilt.</p><div class="warning custom-block"><p class="custom-block-title">Wichtig</p><p>Die Statistiken summieren über alle gefundenen Wege. Jeder Weg bringt seine Kabel, Netzknoten und Trassen erneut mit, sodass bei vielen Fasern Zahlen zustande kommen, die weit über dem liegen, was das Projekt überhaupt enthält – ein Netzknoten mit einigen hundert Fasern meldet leicht mehrere tausend Gräben. Als Größenordnung sind die Werte brauchbar, als Anzahl nicht.</p></div><p>Der <strong>Einstiegspunkt</strong> wiederholt, wonach gesucht wurde, mit der Art des Objekts als Kennzeichnung davor.</p><p>Die <strong>Kabelinfrastruktur</strong> nennt je Kabel des Weges, wo es liegt. Aufgeklappt steht darin das „Mikrorohr“ mit Nummer, Farbe und Status, das „Rohr“ mit Namen und Rohrtyp, die „Geometrie“ mit Art und Länge sowie die „Gräben“ – jeder mit Trassen-ID, Bauart und Länge. Die Markierung „GEO“ hinter einer Trasse bedeutet, dass ihre Geometrie mitgeladen wurde, siehe Abschnitt <a href="#_15-6-geometrie-modus-ausrichtung-geojson-download">Geometrie</a>.</p><p>Unter <strong>„Faserwege“</strong> steht der Weg selbst – als Baum, wenn Sie von einer Faser aus gesucht haben, und sonst als Tabelle.</p><p><strong>Der Baum</strong></p><p>Jede Station des Weges beginnt mit der Faser („F1“), dem Kabel und dessen Kabeltyp, und wenn der Weg dort über einen Spleiß weitergeht, mit dem Netzknoten dahinter. Darunter stehen die beiden Endknoten des Kabels und die Farbpunkte von Faser und Bündel.</p><p><img src="'+o+'" alt="Screenshot des Ergebnisses eines Faserwegs für eine Faser mit Hervorhebung des Baums und der geöffneten Details" data-zoomable="true"></p><p>„Details“ klappt die Angaben zur Station auf:</p><ul><li><strong>Faser</strong> – „Bündel“, „Faser im Bündel“, die beiden Farben, „Layer“ und der Status.</li><li><strong>„Spleiss“</strong> – der Port, an dem die Faser aufliegt, mit Komponente, Slots und Seite. Der <strong>„Containerpfad“</strong> nennt die Container, in denen diese Komponente steckt („Rack: RACK-A1“), siehe Abschnitt <a href="./02-grundbegriffe-und-datenmodell.html#_2-3-netzknoten-container-slots-komponenten-und-ports">Netzknoten, Container, Slots, Komponenten und Ports</a>.</li><li><strong>„Endpunkt (keine Verbindung)“</strong> – die Faser liegt auf einem Port, von dem aus es nicht weitergeht. Hier endet der Weg.</li><li><strong>„Kabelpfad“</strong> – Anfang und Ende des Kabels mit „START“ und „ENDE“, dazu die Adressen dieser Netzknoten, sofern sie eine haben.</li><li><strong>„Adresse“</strong> und <strong>„Wohneinheit“</strong> – das Ziel, siehe Abschnitt <a href="#_15-5-betroffene-adressen-und-wohneinheiten">Betroffene Adressen und Wohneinheiten</a>.</li></ul><p>Jeder Spleiß rückt die nächste Station eine Stufe ein. Teilt sich der Weg – etwa hinter einem Splitter –, stehen mehrere Stationen auf derselben Stufe, und die Statistik meldet „Verzweigungen: Ja“.</p><div class="info custom-block"><p class="custom-block-title">Hinweis</p><p>Die Schaltflächen im Baum tun zwei verschiedene Dinge. Faser, Kabel, Netzknoten und Adresse in den ersten Zeilen einer Station <strong>markieren</strong> das Objekt in der Karte, sofern sie eingeblendet ist (siehe Abschnitt <a href="#_15-6-geometrie-modus-ausrichtung-geojson-download">Geometrie</a>); ohne Karte bewirken sie nichts. Die Netzknoten- und Adress-Schaltflächen <strong>in den Details</strong> – unter „Endpunkt“, „Kabelpfad“ und „Adresse:“ – starten dagegen einen neuen Faserweg von diesem Objekt aus.</p></div><p><strong>Die Tabelle</strong></p><p>Bei allen anderen Einstiegspunkten kommen viele Wege zusammen, und „Faserwege“ zeigt sie als Tabelle mit den Spalten „Faser“, „Kabel“, „Farben“, „Ende“ und „Wohneinheiten“. Endet ein Weg an mehreren Stellen, steht in „Ende“ „Mehrere Ziele“ mit deren Anzahl; ein Zeigen mit der Maus nennt sie.</p><p><img src="'+u+'" alt="Screenshot des Ergebnisses eines Faserwegs für einen Netzknoten mit Hervorhebung der gefilterten Tabelle und einer aufgeklappten Zeile" data-zoomable="true"></p><p>Das Feld darüber filtert nach Fasernummer, Kabelname und Ziel; rechts darin steht, wie viele Wege der Filter übrig lässt („144 / 696“). Der Pfeil am rechten Rand einer Zeile klappt den Baum dieses Weges auf – denselben, den der Faser-Einstieg für sich allein zeigt. Unter der Tabelle steht die Zahl der gefilterten Wege.</p><h2 id="_15-3-modus-„weg-und-modus-„signalanalyse" tabindex="-1">15.3 Modus „Weg“ und Modus „Signalanalyse“ <a class="header-anchor" href="#_15-3-modus-„weg-und-modus-„signalanalyse" aria-label="Permalink to &quot;15.3 Modus „Weg“ und Modus „Signalanalyse“&quot;">​</a></h2><p>Sind Sie von einer <strong>Faser</strong> aus eingestiegen, steht über dem Ergebnis ein Umschalter mit zwei Modi:</p><ul><li><strong>„Weg“</strong> beantwortet, wo die Faser entlangläuft und wo sie endet. Das ist der Modus der beiden vorigen Abschnitte.</li><li><strong>„Signalanalyse“</strong> beantwortet, was von einer gewählten Signalquelle aus tatsächlich versorgt wird und wo das Signal aufhört.</li></ul><p>Bei allen anderen Einstiegspunkten fehlt der Umschalter; dort gibt es nur den Weg.</p><h2 id="_15-4-signalquelle-signalreichweite-und-unterbrechungen" tabindex="-1">15.4 Signalquelle, Signalreichweite und Unterbrechungen <a class="header-anchor" href="#_15-4-signalquelle-signalreichweite-und-unterbrechungen" aria-label="Permalink to &quot;15.4 Signalquelle, Signalreichweite und Unterbrechungen&quot;">​</a></h2><p>Die <strong>„Signalquelle“</strong> ist der Netzknoten, von dem aus gerechnet wird. Die Liste enthält die Anfangs- und Endknoten aller Kabel des Weges, jeweils mit dem Hinweis, ob das Kabel dort beginnt („Kabelanfang“) oder endet („Kabelende“); die Voreinstellung ist mit „(Standard)“ gekennzeichnet. Eine andere Quelle rechnet den Weg sofort neu.</p><p><img src="'+h+'" alt="Screenshot der Signalanalyse einer Faser mit Signalquelle, Auswirkungsübersicht und der Karte des Faserwegs" data-zoomable="true"></p><p>Darunter steht das Ergebnis:</p><ul><li>Sind alle Fasern versorgt, meldet Qonnectra „Keine Unterbrechungen erkannt - alle Fasern sind aktiv“.</li><li>Andernfalls steht dort „Unterbrechungspunkt“ mit deren Anzahl und je Unterbrechung ein Kasten mit Faser, Kabel und dem Netzknoten, an dem der Weg abbricht.</li></ul><p>Die <strong>„Auswirkungsübersicht“</strong> stellt jeweils „Aktiv“ und „Dunkel“ gegenüber: „Fasern“, „Netzknoten“, „Betroffene Adressen“, „Betroffene Wohneinheiten“ und die „Signalreichweite“ in Metern – die Summe der Kabellängen, die vom Signal erreicht werden.</p><p>Der Baum unter „Signalanalyse“ ist derselbe wie im Modus „Weg“, jede Station aber zusätzlich mit „Aktiv“, „Kein Signal“ oder „Unterbrechungspunkt“ gekennzeichnet.</p><div class="info custom-block"><p class="custom-block-title">Hinweis</p><p>Die Signalanalyse lädt die Geometrie immer mit und zeigt deshalb auch immer die Karte, unabhängig von der Option „Geometrie einbeziehen“, siehe Abschnitt <a href="#_15-6-geometrie-modus-ausrichtung-geojson-download">Geometrie</a>.</p></div><div class="warning custom-block"><p class="custom-block-title">Wichtig</p><p>Eine Unterbrechung ist keine gemeldete Störung, sondern eine Lücke in der Dokumentation: An dieser Stelle fehlt der Spleiß, der weiterführen würde. Was bei einem <strong>Schaden</strong> ausfällt, rechnet die Störungsanalyse aus, siehe Kapitel <a href="./06-stoerungsanalyse.html">Störungsanalyse</a>.</p></div><h2 id="_15-5-betroffene-adressen-und-wohneinheiten" tabindex="-1">15.5 Betroffene Adressen und Wohneinheiten <a class="header-anchor" href="#_15-5-betroffene-adressen-und-wohneinheiten" aria-label="Permalink to &quot;15.5 Betroffene Adressen und Wohneinheiten&quot;">​</a></h2><p>Am Ende eines Faserwegs steht, wer daran hängt. Im Modus „Weg“ finden Sie das in den Details der letzten Station: der Kasten <strong>„Adresse“</strong> mit Adress-ID, Ortsteil, Ausbaustatus, Projekt und Kennzeichen und der Kasten <strong>„Wohneinheit“</strong> mit Etage, Seite, Gebäudeteil, Typ, Status und – falls erfasst – dem Bewohner. Die Schaltfläche mit der Adresse darunter („Adresse:“) führt zum Faserweg dieser Adresse.</p><p>Im Modus „Signalanalyse“ stehen dieselben Angaben, zusätzlich mit „Kein Signal“ gekennzeichnet, wenn sie hinter einer Unterbrechung liegen; die Zahlen dazu nennt die „Auswirkungsübersicht“.</p><p>Wohneinheiten erscheinen nur, wenn sie im Netzschema auf einen Port gelegt wurden, siehe Abschnitt <a href="./14-netzschema.html#_14-8-spleiße-und-ports">Spleiße und Ports</a>. Adressen erscheinen auch ohne das – über den Netzknoten, an dem das Kabel endet, sofern diesem eine Adresse zugeordnet ist.</p><div class="info custom-block"><p class="custom-block-title">Hinweis</p><p>„Adressen: 0“ und „Wohneinheiten: 0“ bedeuten also nicht, dass niemand versorgt wird, sondern dass auf diesem Weg nichts dokumentiert ist, was ein Ziel wäre. Bei einem Zubringerkabel zwischen zwei Verteilern ist das der Normalfall.</p></div><h2 id="_15-6-geometrie-modus-ausrichtung-geojson-download" tabindex="-1">15.6 Geometrie: Modus, Ausrichtung, GeoJSON-Download <a class="header-anchor" href="#_15-6-geometrie-modus-ausrichtung-geojson-download" aria-label="Permalink to &quot;15.6 Geometrie: Modus, Ausrichtung, GeoJSON-Download&quot;">​</a></h2><p>Ein Faserweg wird ohne Geometrie ermittelt: Die Verfolgung braucht nur Kabel und Spleiße. Wollen Sie den Weg auch in der Karte sehen oder als Datei mitnehmen, kreuzen Sie vor der Suche „Geometrie einbeziehen“ an. Darauf erscheinen zwei weitere Optionen.</p><p><img src="'+g+'" alt="Screenshot der Ansicht Faserweg mit Hervorhebung der Optionen und dem eingeschalteten Feld „Geometrie einbeziehen“" data-zoomable="true"></p><p>Der <strong>„Modus“</strong> bestimmt, wie die Linien gebildet werden:</p><ul><li><strong>„Segmente“</strong> – jede Trasse als eigene Linie. So sehen Sie, aus welchen Abschnitten der Weg besteht.</li><li><strong>„Zusammengeführt“</strong> – eine Linie je Kabel.</li><li><strong>„Geroutet“</strong> – der berechnete kürzeste Weg zwischen Anfangs- und Endknoten des Kabels.</li></ul><p><strong>„Nach Kabelrichtung ausrichten“</strong> dreht die Segmente so, dass sie vom Anfangs- zum Endknoten verlaufen. Ohne diese Option behalten sie die Richtung, in der die Trasse erfasst wurde.</p><p>Beim Einstieg über eine Faser rückt das Ergebnis daraufhin nach links, und rechts daneben steht die Karte mit dem Weg.</p><p><img src="'+c+'" alt="Screenshot des Ergebnisses eines Faserwegs mit der Karte rechts und der Schaltfläche „GeoJSON herunterladen“" data-zoomable="true"></p><p>Karte und Baum sind miteinander verbunden: Ein Klick auf einen Netzknoten, eine Adresse oder eine Wohneinheit im Baum rückt das Objekt in den Kartenausschnitt und hebt es hervor; umgekehrt markiert ein Klick in der Karte den Eintrag im Baum. Für ein Kabel gilt das nur im Modus „Zusammengeführt“ – in „Segmente“ besteht die Linie aus den einzelnen Trassen, und die Karte findet dann kein Kabel zum Hervorheben. Die Faser-Schaltfläche hat in der Karte gar kein Gegenstück; sie bewirkt dort nichts.</p><p>„GeoJSON herunterladen“ speichert den Weg als Datei: Kabel und Trassen als Linien, Netzknoten und Adressen als Punkte, dazu ihre Eigenschaften. Die Datei liegt im Koordinatensystem des Projekts, siehe Abschnitt <a href="./03-wiederkehrende-bedienelemente.html#_3-8-exportformate-im-uberblick">Exportformate im Überblick</a>.</p><div class="warning custom-block"><p class="custom-block-title">Wichtig</p><p>„Geometrie einbeziehen“ lässt sich nur vor der Suche setzen. Auf der Ergebnisseite gibt es keinen Umschalter dafür: Gehen Sie mit „Zurück“ zur Auswahl, kreuzen Sie die Option an und suchen Sie erneut.</p></div><div class="info custom-block"><p class="custom-block-title">Hinweis</p><p>Die Karte erscheint ausschließlich beim Einstieg über eine Faser. Bei allen anderen Einstiegspunkten wirkt die Option nur auf den Download und auf die Angaben unter „Kabelinfrastruktur“.</p></div><h2 id="_15-7-uber-alle-projekte-suchen" tabindex="-1">15.7 Über alle Projekte suchen <a class="header-anchor" href="#_15-7-uber-alle-projekte-suchen" aria-label="Permalink to &quot;15.7 Über alle Projekte suchen&quot;">​</a></h2><p>Die Suche ist auf das ausgewählte Projekt beschränkt. Das Kästchen „Alle Projekte durchsuchen“ hebt diese Grenze auf – dann stehen auch Adressen, Netzknoten und Kabel der anderen Projekte in der Trefferliste.</p><div class="info custom-block"><p class="custom-block-title">Hinweis</p><p>Die Verfolgung selbst kennt keine Projektgrenze: Sie folgt den Spleißen, egal zu welchem Projekt das nächste Kabel gehört. Die Option betrifft nur, was Sie als Einstiegspunkt finden können.</p></div><div class="warning custom-block"><p class="custom-block-title">Wichtig</p><p>Die Trefferliste nennt das Projekt nicht. Bei gleichnamigen Objekten in mehreren Projekten – etwa einem Netzknoten „PoP-1“ – lässt sich anhand der Liste nicht entscheiden, welcher gemeint ist. In welchem Projekt Sie gelandet sind, sehen Sie danach an der Angabe „Projekt“ in den Details der Adresse.</p></div>',68)])])}const K=n(m,[["render",b]]);export{A as __pageData,K as default};
